'use strict';
const $ = id => document.getElementById(id);
const topics = ['Communication','Studying','Campus life','Adjustments'];
const guides = [
 {id:'communication',title:'Making communication clearer',topic:'Communication',keywords:'feedback explicit instructions group work email',intro:'Use these prompts to agree on how to communicate, rather than guessing what the other person means.',steps:['Ask: “Would written steps, an example, or a conversation be most useful?”','Check understanding: “My understanding is that we need to do X by Friday. Is that right?”','Agree on a reply window and how to signal when something is urgent.'],prompt:'Would it help if we wrote down the next steps together?',source:'Oxford: student support plans',url:'https://www.ox.ac.uk/students/welfare/disability/support'},
 {id:'studying',title:'Finding a manageable first step',topic:'Studying',keywords:'deadlines executive function task initiation planning assignments',intro:'A conversation starter for an assignment that feels difficult to begin. Try an approach only if the person finds it useful.',steps:['Ask which part feels unclear: the instructions, the starting point, or the workload.','Choose one small, concrete action together, such as opening the brief or making a list of questions.','Agree on whether a check-in would help, and let the person choose when.'],prompt:'What is one small step that would feel manageable today?',source:'Oxford: study support resources',url:'https://www.ox.ac.uk/students/welfare/disability/support'},
 {id:'sensory',title:'Talking about the campus environment',topic:'Campus life',keywords:'sensory noise quiet space crowded library overload',intro:'Different people find different environments comfortable. Ask about the setting before making a plan.',steps:['Ask about preferred noise level, lighting, and group size.','Offer options such as text, a quiet space, or a shorter meeting.','Make it easy to take a break or change the arrangement.'],prompt:'Would a quieter space or a text conversation work better for you?',source:'UvA: studying with a disability',url:'https://student.uva.nl/en/categories/studying-with-a-disability'},
 {id:'adjustments',title:'Preparing to ask for university support',topic:'Adjustments',keywords:'accommodations disability adviser exam extra time facilities',intro:'Each university has its own process. Peers can help prepare questions; the university confirms what support is available.',steps:['Describe the study situation and the barrier you are encountering.','Write down questions for your study adviser or disability support service.','Check the process, deadlines, and documentation with your own university.'],prompt:'Would you like help drafting a question for your university’s support team?',source:'UvA: student support and facilities',url:'https://student.uva.nl/en/categories/studying-with-a-disability'},
 {id:'preferences',title:'Understanding someone’s preferences',topic:'Communication',keywords:'neurodiversity neurodivergence autism ADHD identity individual consent',intro:'A group label does not tell you everything about a person. Use the conversation to learn what they want you to know.',steps:['Ask what would make this interaction easier.','Let the person decide what to share about their identity or diagnosis.','Check before giving advice: “Would you like ideas, help with a task, or someone to listen?”'],prompt:'Would you prefer suggestions, practical help, or just space to talk?',source:'Oxford: individual student support',url:'https://www.ox.ac.uk/students/welfare/disability/support'}
];
const seed = () => ({questions:[
 {id:'seed-1',title:'How do I ask my group to be more specific about tasks?',body:'Our project chat moves quickly and I’m not sure which tasks are mine. I’d like to ask for clearer expectations without making it awkward.',topic:'Communication',name:'Alex',role:'Student',university:'Example campus A',mine:false,offers:[]},
 {id:'seed-2',title:'I know the deadline. Starting is the hard part.',body:'I have an essay due next week, but breaking it into steps is overwhelming. Has anyone found a way to make the first step smaller?',topic:'Studying',name:'Sam',role:'Student',university:'Example campus B',mine:false,offers:[]},
 {id:'seed-3',title:'How can I explain that I need a quieter meeting space?',body:'I’m a staff member and our shared office gets quite noisy. I’d appreciate help finding the words to ask for a different meeting setting.',topic:'Campus life',name:'Morgan',role:'Staff member',university:'Example campus C',mine:false,offers:[]}
],chats:[]});
let state = seed();
try {const saved=JSON.parse(localStorage.getItem('common-ground-v1')); if(saved && Array.isArray(saved.questions)&&Array.isArray(saved.chats)) state=saved;} catch {}
let currentChat = null, offerQuestion = null, toastTimer;
const escape = x => String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4500);}
function save(){try{localStorage.setItem('common-ground-v1',JSON.stringify(state));}catch{toast('Browser storage is unavailable. Changes will last for this visit.');}}
function renderQuestions(){
 const selected=$('filter').value; const qs=state.questions.filter(q=>selected==='All topics'||q.topic===selected);
 $('question-count').textContent=state.questions.length;
 $('question-feed').innerHTML=qs.length?qs.map(q=>`<article class="question"><div class="question-meta"><span class="chip">${escape(q.topic)}</span><span>${escape(q.name)} · ${escape(q.role)}</span>${q.university?`<span>${escape(q.university)}</span>`:''}<span>${q.mine?'Your local post':'Example question'}</span></div><h3>${escape(q.title)}</h3><p>${escape(q.body)}</p><div class="question-actions"><button class="${q.mine?'secondary':'primary'}" data-action="${q.mine?'example-offer':'offer'}" data-id="${escape(q.id)}">${q.mine?'Try an example help offer':'Offer help'}</button><button class="text-button" data-action="guide" data-topic="${escape(q.topic)}">Related guide</button></div>${q.offers.map(o=>`<div class="offer"><strong>${escape(o.name)} · Example offer</strong><p>${escape(o.text)}</p>${o.status==='pending'?`<button class="primary" data-action="accept" data-id="${escape(q.id)}" data-offer="${escape(o.id)}">${q.mine?'Accept & open demo conversation':'Simulate author accepting'}</button> <button class="text-button" data-action="decline" data-id="${escape(q.id)}" data-offer="${escape(o.id)}">Decline</button>`:`<span class="small">${o.status==='accepted'?'Accepted in demo':'Declined in demo'}</span>`}</div>`).join('')}</article>`).join(''):'<p class="empty">No questions on this topic yet. You can post the first one.</p>';
}
function renderGuides(query=''){
 const s=query.toLowerCase().trim();const list=guides.filter(g=>[g.title,g.topic,g.keywords,g.intro].join(' ').toLowerCase().includes(s));
 $('guide-list').innerHTML=list.length?list.map(g=>`<article class="guide-card"><span class="chip">${g.topic}</span><h3>${g.title}</h3><p>${g.intro}</p><ul>${g.steps.map(t=>`<li>${t}</li>`).join('')}</ul><p><strong>Try asking:</strong> “${g.prompt}”</p><a href="${g.url}" target="_blank" rel="noopener noreferrer">${g.source}</a><p class="small">Conversation prompts written for this prototype. Source links offer further university support information; they are not an endorsement of this app.</p></article>`).join(''):'<p class="empty">No guide matches yet. Try “communication”, “study”, or “sensory”.</p>';
}
function tab(which){const guide=which==='guide';$('questions-pane').hidden=guide;$('guide-pane').hidden=!guide;for(const [id,on] of [['questions-tab',!guide],['guide-tab',guide]]){$(id).setAttribute('aria-selected',String(on));$(id).tabIndex=on?0:-1;}}
function view(which){const chat=which==='chat';$('community-view').hidden=chat;$('conversations-view').hidden=!chat;$('community-nav').classList.toggle('active',!chat);$('conversation-nav').classList.toggle('active',chat);if(chat)renderChats();}
function related(topic){view('community');tab('guide');$('guide-search').value=topic;renderGuides(topic);$('guide-tab').focus();}
function postQuestion(input){
 const title=String(input.title??'').trim(),body=String(input.body??'').trim();
 if(!title||!body||title.length>140||body.length>2000||!topics.includes(input.topic))throw new Error('Enter a question, context, and a valid topic.');
 const q={id:crypto.randomUUID(),title,body,topic:input.topic,name:String(input.name||'You').trim().slice(0,40)||'You',role:input.role==='Staff member'?'Staff member':'Student',university:String(input.university||'').trim().slice(0,80),mine:true,offers:[]};
 state.questions.unshift(q);save();$('filter').value='All topics';tab('questions');renderQuestions();return {id:q.id,title:q.title,localOnly:true};
}
$('question-form').addEventListener('submit',e=>{e.preventDefault();try{postQuestion({title:$('question-title').value,body:$('question-body').value,topic:$('topic').value,name:$('alias').value,role:$('role').value,university:$('university').value});$('question-form').reset();toast('Your question is in the shared space. Saved in this browser only.');$('shared-title').scrollIntoView({block:'start',behavior:'auto'});}catch(err){toast(err.message);}});
$('filter').addEventListener('change',renderQuestions);
$('guide-search').addEventListener('input',()=>renderGuides($('guide-search').value));
$('questions-tab').onclick=()=>tab('questions');$('guide-tab').onclick=()=>tab('guide');
for(const id of ['questions-tab','guide-tab'])$(id).addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'questions':e.key==='End'?'guide':id==='questions-tab'?'guide':'questions';tab(next);$(next+'-tab').focus();}});
$('open-guide').onclick=()=>{tab('guide');$('guide-tab').focus();};
$('help-focus').onclick=()=>{tab('questions');$('questions-tab').focus();};
$('community-nav').onclick=()=>view('community');$('conversation-nav').onclick=()=>view('chat');$('back-community').onclick=()=>view('community');
$('question-feed').addEventListener('click',e=>{
 const b=e.target.closest('button[data-action]');if(!b)return;const action=b.dataset.action;
 if(action==='guide'){related(b.dataset.topic);return;}const q=state.questions.find(x=>x.id===b.dataset.id);if(!q)return;
 if(action==='offer'){offerQuestion=q.id;$('offer-question').textContent=q.title;$('offer-dialog').showModal();}
 if(action==='example-offer'){q.offers.push({id:crypto.randomUUID(),name:'Jamie L.',text:'Would it help to talk through the next step together? We can keep it in text and take our time.',status:'pending'});save();renderQuestions();toast('Example offer added. You can accept or decline it.');}
 if(action==='accept'){const o=q.offers.find(x=>x.id===b.dataset.offer);if(!o||o.status!=='pending')return;o.status='accepted';const chat={id:crypto.randomUUID(),name:q.mine?o.name:q.name,context:q.title,messages:[{author:'Demo context',text:'You both agreed to connect in this example. Use a shared guide or add a message to explore the interaction.',mine:false}],ended:false};state.chats.push(chat);currentChat=chat.id;save();renderQuestions();view('chat');$('chat-name').tabIndex=-1;$('chat-name').focus();}
 if(action==='decline'){const o=q.offers.find(x=>x.id===b.dataset.offer);if(o&&o.status==='pending'){o.status='declined';save();renderQuestions();toast('Demo offer declined. No conversation was opened.');}}
});
$('offer-close').onclick=()=>$('offer-dialog').close();
$('offer-form').addEventListener('submit',e=>{e.preventDefault();const q=state.questions.find(x=>x.id===offerQuestion);if(!q)return;q.offers.push({id:crypto.randomUUID(),name:$('helper-name').value.trim()||'Helper',text:$('offer-message').value.trim(),status:'pending'});save();renderQuestions();$('offer-dialog').close();$('offer-form').reset();toast('Demo offer created. Try simulating the author’s acceptance.');});
function renderChats(){
 $('chat-count').textContent=state.chats.filter(c=>!c.ended).length;
 $('conversation-list').innerHTML=state.chats.length?state.chats.map(c=>`<button class="conversation-item" data-chat="${escape(c.id)}"><strong>${escape(c.name)}</strong><span>${escape(c.context)}</span>${c.ended?'<span>Ended</span>':''}</button>`).join(''):'<p class="empty">No connections yet.</p>';
 const c=state.chats.find(c=>c.id===currentChat);$('chat-empty').hidden=!!c;$('chat-content').hidden=!c;
 $('chat-guides').innerHTML=guides.map(g=>`<button data-guide="${g.id}">${g.title}<span class="small"> · Add reference</span></button>`).join('');
 if(!c)return;$('chat-name').textContent=c.name;$('chat-context').textContent=c.context;$('close-chat').disabled=c.ended;$('close-chat').textContent=c.ended?'Connection ended':'End demo connection';$('message-form').hidden=c.ended;
 $('messages').innerHTML=c.messages.map(m=>`<div class="message ${m.mine?'mine':''} ${m.guide?'reference':''}"><span class="small">${escape(m.author)}</span><p>${escape(m.text)}</p>${m.guide?`<button class="text-button" data-open-guide="${escape(m.guide)}">Read this guide</button>`:''}</div>`).join('');
}
$('conversation-list').onclick=e=>{const b=e.target.closest('[data-chat]');if(b){currentChat=b.dataset.chat;renderChats();}};
$('message-form').onsubmit=e=>{e.preventDefault();const c=state.chats.find(c=>c.id===currentChat),text=$('message').value.trim();if(!c||c.ended||!text)return;c.messages.push({author:'You · local preview',text,mine:true});save();$('message').value='';renderChats();toast('Message added locally. No message was sent.');};
$('chat-guides').onclick=e=>{const b=e.target.closest('[data-guide]'),c=state.chats.find(c=>c.id===currentChat);if(!b)return;if(!c||c.ended){toast('Open an active demo conversation first.');return;}const g=guides.find(g=>g.id===b.dataset.guide);c.messages.push({author:'Shared guide',text:g.title+'\n'+g.prompt,guide:g.id,mine:false});save();renderChats();};
$('messages').onclick=e=>{const b=e.target.closest('[data-open-guide]');if(b){const g=guides.find(g=>g.id===b.dataset.openGuide);related(g.title);}};
$('close-chat').onclick=()=>{const c=state.chats.find(c=>c.id===currentChat);if(!c)return;c.ended=true;save();renderChats();toast('Demo connection ended.');};
$('reset').onclick=()=>{if(!confirm('Remove your local demo posts and messages and restore the examples?'))return;state=seed();currentChat=null;save();$('filter').value='All topics';$('guide-search').value='';renderQuestions();renderChats();renderGuides();view('community');tab('questions');toast('Demo reset.');};
renderQuestions();renderGuides();renderChats();
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 try{Promise.resolve(document.modelContext.registerTool({name:'search_shared_guide',description:'Read practical reference entries in the university peer-support prototype.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200)throw new Error('Provide a query of 200 characters or fewer.');const q=input.query.toLowerCase();return guides.filter(g=>[g.title,g.topic,g.keywords].join(' ').toLowerCase().includes(q)).map(g=>({title:g.title,prompt:g.prompt,source:g.url}));}},{signal:lifecycle.signal})).catch(()=>{});
 Promise.resolve(document.modelContext.registerTool({name:'create_local_demo_question',description:'Create a device-local question in the neurodivergent group prototype. This does not publish to other users.',inputSchema:{type:'object',properties:{title:{type:'string',maxLength:140},body:{type:'string',maxLength:2000},topic:{type:'string',enum:topics}},required:['title','body','topic'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){return postQuestion(input);}},{signal:lifecycle.signal})).catch(()=>{});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}catch{}
}
